const HASHED = /[.-][0-9a-f]{20,}\.\w+$/;
const OPTIONAL = /^assets\//;   // a photo that failed to download is fetched again the first time it is shown
const PAGES = FILES.filter((f) => /\.html$/.test(f) && f !== 'index.html').map((f) => new URL(f, self.registration.scope).pathname);

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.all(FILES.map(async (file) => {
      const url = new URL(file, self.registration.scope).href;
      try {
        const kept = HASHED.test(file) && (await caches.match(url));
        const res = kept || (await fetch(url, { cache: 'reload' }));
        if (!res.ok) throw new Error(file + ': ' + res.status);
        await cache.put(url, res);
      } catch (e) {
        if (!OPTIONAL.test(file)) throw e;
      }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('gym-tracker-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || !req.url.startsWith(self.registration.scope)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = req.mode === 'navigate' && !PAGES.includes(new URL(req.url).pathname)
      ? await cache.match(new URL('index.html', self.registration.scope).href)
      : await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    const res = await fetch(req);
    if (res.ok && req.mode !== 'navigate') cache.put(req, res.clone()).catch(() => {});
    return res;
  })());
});
